// couponApi.js
import api from "./axios";

export const fetchMyCoupons = () => api.get("/coupons/my");
export const redeemCoupon = (couponId) => api.post(`/coupons/redeem/${couponId}`);
export const createCoupon = (payload) => api.post("/coupons", payload); // admin-ish
